create table if not exists public.merch_prospects (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, company_name text, domain text, contact_name text, email text, phone text, source text, source_url text, fit_score integer check (fit_score between 0 and 100), status text not null default 'discovered' check (status in ('discovered','qualified','draft_ready','approved','contacted','replied','converted','rejected','suppressed')), notes text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), last_contact_at timestamptz, next_action_at timestamptz);
create unique index if not exists merch_prospects_org_email_uq on public.merch_prospects(organization_id, lower(email)) where email is not null and email <> '';
create index if not exists merch_prospects_status_idx on public.merch_prospects(organization_id,status,fit_score desc,created_at desc);
create table if not exists public.merch_outreach_drafts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, prospect_id uuid not null references public.merch_prospects(id) on delete cascade, channel text not null check (channel in ('email','whatsapp','instagram','facebook','other')), subject text, body text not null, personalization jsonb not null default '{}'::jsonb, status text not null default 'draft' check (status in ('draft','approved','sent','rejected','cancelled')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), approved_at timestamptz, sent_at timestamptz);
create index if not exists merch_outreach_status_idx on public.merch_outreach_drafts(organization_id,status,created_at desc);
create table if not exists public.merch_creative_proposals (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, prospect_id uuid references public.merch_prospects(id) on delete set null, product_id uuid references public.merch_products(id) on delete set null, provider text not null, prompt text not null, image_url text, preview_url text, variant text, score integer check (score between 0 and 100), status text not null default 'candidate' check (status in ('candidate','selected','approved','rejected','sent')), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), selected_at timestamptz);
create index if not exists merch_creative_proposals_batch_idx on public.merch_creative_proposals(organization_id,prospect_id,created_at desc);
alter table public.merch_prospects enable row level security;
alter table public.merch_outreach_drafts enable row level security;
alter table public.merch_creative_proposals enable row level security;
create policy merch_prospects_member_select on public.merch_prospects for select using (exists (select 1 from public.memberships m where m.organization_id=merch_prospects.organization_id and m.user_id=auth.uid()));
create policy merch_prospects_manager_write on public.merch_prospects for all using (exists (select 1 from public.memberships m where m.organization_id=merch_prospects.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin','manager'))) with check (exists (select 1 from public.memberships m where m.organization_id=merch_prospects.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin','manager')));
create policy merch_outreach_member_select on public.merch_outreach_drafts for select using (exists (select 1 from public.memberships m where m.organization_id=merch_outreach_drafts.organization_id and m.user_id=auth.uid()));
create policy merch_outreach_manager_write on public.merch_outreach_drafts for all using (exists (select 1 from public.memberships m where m.organization_id=merch_outreach_drafts.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin','manager'))) with check (exists (select 1 from public.memberships m where m.organization_id=merch_outreach_drafts.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin','manager')));
create policy merch_creative_member_select on public.merch_creative_proposals for select using (exists (select 1 from public.memberships m where m.organization_id=merch_creative_proposals.organization_id and m.user_id=auth.uid()));
create policy merch_creative_manager_write on public.merch_creative_proposals for all using (exists (select 1 from public.memberships m where m.organization_id=merch_creative_proposals.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin','manager'))) with check (exists (select 1 from public.memberships m where m.organization_id=merch_creative_proposals.organization_id and m.user_id=auth.uid() and m.role in ('owner','admin','manager')));